ALTER TABLE users ADD COLUMN phone VARCHAR(30), ADD COLUMN role VARCHAR(20) NOT NULL DEFAULT 'CUSTOMER', ADD COLUMN created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, ADD COLUMN updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE categories ADD COLUMN description TEXT, ADD COLUMN created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, ADD COLUMN updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE books ADD COLUMN isbn VARCHAR(30), ADD COLUMN description TEXT, ADD COLUMN image_url VARCHAR(500), ADD COLUMN publication_date DATE, ADD COLUMN created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, ADD COLUMN updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP;
CREATE TABLE authors (id BIGSERIAL PRIMARY KEY, name VARCHAR(200) NOT NULL, biography TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE publishers (id BIGSERIAL PRIMARY KEY, name VARCHAR(200) NOT NULL, address VARCHAR(500), website VARCHAR(300), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE books ADD COLUMN author_id BIGINT REFERENCES authors(id), ADD COLUMN publisher_id BIGINT REFERENCES publishers(id);
CREATE TABLE carts (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE REFERENCES users(id), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cart_items (id BIGSERIAL PRIMARY KEY, cart_id BIGINT NOT NULL REFERENCES carts(id) ON DELETE CASCADE, book_id BIGINT NOT NULL REFERENCES books(id), quantity INT NOT NULL CHECK(quantity > 0), UNIQUE(cart_id, book_id));
ALTER TABLE orders ADD COLUMN user_id BIGINT REFERENCES users(id), ADD COLUMN shipping_address VARCHAR(500), ADD COLUMN phone VARCHAR(30), ADD COLUMN updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP;
CREATE TABLE payments (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL UNIQUE REFERENCES orders(id), amount NUMERIC(12,2) NOT NULL, method VARCHAR(30) NOT NULL, status VARCHAR(30) NOT NULL, transaction_code VARCHAR(100), paid BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE reviews (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), book_id BIGINT NOT NULL REFERENCES books(id), rating INT NOT NULL CHECK(rating BETWEEN 1 AND 5), comment TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id, book_id));
CREATE INDEX idx_books_title ON books(title);
